action.query:
query Query($where: QualitySpecificationWhereInput, $orderBy: [QualitySpecificationOrderByInput!], $first: Int, $after: String) {
  qualitySpecification(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        name
        lowerBound
        upperBound
        usable
        code
        description
        expectedValue
        unitId
        unit{
          id
          name
        }
        typeId
        type {
          id
          name
        }
      }
    }
  }
}

