action.query:
query Query($whereSpecs: QualitySpecificationListWhereInput, $whereSubjects: QualitySubjectListWhereInput) {
  qualitySpecificationList(where: $whereSpecs) {
    edges {
      node {
        id
        usable
        order
        attachmentId
        specificationGroupId
        specificationId
      }
    }
},
  qualitySubjectList(where: $whereSubjects) {
    edges {
      node {
        id
        intervalId
        sampleSize
        usable
        specificationGroupId
        typeId
        processId
        productId
        productProcessId
        workcenterId
        interval {
          value
          unitId
        }
      }
    }
  }
}

